import{_ as t,o as a,c as r,a0 as o}from"./chunks/framework.69uO77x_.js";const m=JSON.parse('{"title":"Platform","description":"","frontmatter":{},"headers":[],"relativePath":"api/auth-foundation/Platform/index.md","filePath":"api/auth-foundation/Platform/index.md"}'),n={name:"api/auth-foundation/Platform/index.md"};function s(i,e,d,l,c,f){return a(),r("div",null,[...e[0]||(e[0]=[o('<p><a href="./..">@okta/auth-foundation</a> / Platform</p><h1 id="platform" tabindex="-1">Platform <a class="header-anchor" href="#platform" aria-label="Permalink to &quot;Platform&quot;">​</a></h1><p><code>Platform</code> is a registry of platform-wide <strong>singleton</strong> dependencies (time, DPoP key signing, DPoP nonce storage, etc.) that are shared across the whole SDK ecosystem, rather than constructed per-instance by whatever class happens to need them.</p><p>Some of these dependencies vary by JS environment - <code>DPoPSigningAuthority</code> and <code>DPoPNonceCache</code> need genuinely different implementations in a browser vs. React Native, since they lean on environment-specific crypto/storage APIs. Others, like <code>TimeCoordinator</code>, aren&#39;t tied to any particular runtime at all; they&#39;re registered here simply because the SDK needs exactly <em>one</em> shared instance (e.g. for clock-skew coordination) rather than one per consumer. Either way, funneling both kinds of dependency through the same <code>Platform</code> registry gives every part of the SDK one consistent, easy pattern for overriding behavior, instead of each dependency inventing its own configuration mechanism.</p><p>Most consumers never need to touch this module directly. Platform packages like <a href="/api/spa-platform/">@okta/spa-platform</a> or <a href="/api/spa-platform/">@okta/react-native-platform</a> already register the right implementations for their environment, and importing from <code>@okta/auth-foundation</code> pulls in working defaults out of the box.</p><p>Reach for <code>Platform</code> yourself only if you need to override a specific dependency (for example, providing a custom <code>TimeCoordinator</code> in tests) via <a href="./classes/PlatformRegistry#configure">PlatformRegistry.configure</a>, or you&#39;re adding support for a runtime this SDK doesn&#39;t already target, via <a href="./classes/PlatformRegistry#registerdefaultsloader">PlatformRegistry.registerDefaultsLoader</a>.</p><h2 id="remarks" tabindex="-1">Remarks <a class="header-anchor" href="#remarks" aria-label="Permalink to &quot;Remarks&quot;">​</a></h2><p>By convention, every <code>@okta/*</code> SDK package exports a <code>/core</code> entry point alongside its default entry point. The default entry point (e.g. <code>@okta/auth-foundation</code>) calls <a href="./classes/PlatformRegistry#registerdefaultsloader">PlatformRegistry.registerDefaultsLoader</a> on your behalf with that platform&#39;s default implementations already wired up - simple to use, but it means those defaults are always included in your bundle, even if you go on to override them.</p><p>The <code>/core</code> entry point (e.g. <code>@okta/auth-foundation/core</code>) is identical, <em>except</em> it skips that <code>registerDefaultsLoader</code> call. This gives you a way to fully replace a <code>Platform</code> dependency without ever pulling its default implementation into your bundle - useful if the default is heavy, or simply not needed for your use case. If you go this route, you must call <a href="./classes/PlatformRegistry#registerdefaultsloader">PlatformRegistry.registerDefaultsLoader</a> yourself before any other SDK code runs, or <a href="./classes/PlatformRegistryError">PlatformRegistryError</a> will be thrown the first time a dependency is accessed.</p><h2 id="classes" tabindex="-1">Classes <a class="header-anchor" href="#classes" aria-label="Permalink to &quot;Classes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Class</th><th>Description</th></tr></thead><tbody><tr><td><a href="./classes/PlatformRegistryError">PlatformRegistryError</a></td><td>Thrown when the Platform registry cannot resolve a dependency.</td></tr><tr><td><a href="./classes/PlatformRegistry">PlatformRegistry</a></td><td>&gt; [!Warning] &gt; <strong>DO NOT</strong> construct an instance of this <code>PlatformRegistry</code>. Use <code>import { Platform } from &#39;@okta/auth-foundation&#39;</code>.</td></tr></tbody></table><h2 id="interfaces" tabindex="-1">Interfaces <a class="header-anchor" href="#interfaces" aria-label="Permalink to &quot;Interfaces&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Interface</th><th>Description</th></tr></thead><tbody><tr><td><a href="./interfaces/PlatformDependencies">PlatformDependencies</a></td><td>The required Platform dependencies</td></tr></tbody></table>',13)])])}const u=t(n,[["render",s]]);export{m as __pageData,u as default};
